import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { CLIENT_HEADERS, proxyUrl } from '../config';
import { speechChunks } from './speechChunks';
import { loudestOver, voiceLevels } from './voiceLevel';
import type { AthenaBridge } from './UnityAthena';
import warmupHumArpeggioUrl from './voice/warmup-hum-arpeggio.json?url';
import warmupHumScaleUrl from './voice/warmup-hum-scale.json?url';
import warmupMimiUrl from './voice/warmup-mimi.json?url';

/**
 * Neural text-to-speech generated by the Athena backend and played by the
 * embedded Unity avatar. Browser/OS SpeechSynthesis is intentionally not used.
 *
 * Generation takes seconds, so speech is split into two phases: `prepare()`
 * starts fetching the audio immediately and `play()` hands it to Unity. That
 * lets the chat hold Athena's text reveal until the voice can start with it
 * (see AthenaConsole's voice-sync gate); `speak()` remains as the one-shot
 * prepare-then-play convenience.
 *
 * A longer reply is voiced a sentence or so at a time (speechChunks), every
 * part fetched at once: she starts when the first sentence is ready, not the
 * whole reply, and each later part is in hand before the one before it ends.
 */

const STORAGE_KEY = 'companion_tts_enabled';
const GENERATION_TIMEOUT_MS = 30_000;
// Singing runs on a slower model: ~15 s for a four-line song.
const SING_GENERATION_TIMEOUT_MS = 75_000;
// Vocal warm-ups she hums between her spoken lead-in and a song, recorded
// once in her own voice (Pro TTS) so they play instantly. Fetched only the
// first time she sings.
const WARMUP_URLS = [warmupHumArpeggioUrl, warmupHumScaleUrl, warmupMimiUrl];
// One always plays; the rest only cover a song that is still generating.
const MAX_WARMUPS = 3;

let warmupsPromise: Promise<SpeechResponse[]> | null = null;
function loadWarmups(): Promise<SpeechResponse[]> {
  if (!warmupsPromise) {
    const loading = Promise.all(
      WARMUP_URLS.map((url) =>
        fetch(url)
          .then((response) => (response.ok ? (response.json() as Promise<SpeechResponse>) : null))
          .catch(() => null)
      )
    ).then((clips) => clips.filter((clip): clip is SpeechResponse => !!clip?.audioBase64));
    warmupsPromise = loading;
    // A failed load shouldn't stick for the rest of the session.
    void loading.then((clips) => {
      if (!clips.length && warmupsPromise === loading) warmupsPromise = null;
    });
  }
  return warmupsPromise;
}

interface SpeechResponse {
  audioBase64: string;
  sampleRate: number;
  channels: number;
}

interface UnitySpeechPayload extends SpeechResponse {
  requestId: string;
}

interface PendingSpeech {
  id: string;
  abort: AbortController;
  timer: number;
  onEnd?: () => void;
}

export interface PreparedSpeech {
  /**
   * Resolves true once the audio is fetched and can start instantly; false if
   * generation failed, timed out, was cancelled, or TTS is disabled.
   */
  ready: Promise<boolean>;
  /** Hand the audio to Unity. Calls onEnd immediately if there is no audio. */
  play: (onEnd?: () => void) => void;
  cancel: () => void;
}

export interface Speech {
  isSupported: boolean;
  enabled: boolean;
  attachUnity: (bridge: AthenaBridge) => void;
  toggle: () => void;
  /**
   * Begin generating audio for `text` without playing it yet. With `lyrics`,
   * `text` is her spoken lead-in and the lyrics are sung after a warm-up hum.
   */
  prepare: (text: string, options?: { lyrics?: string }) => PreparedSpeech;
  speak: (text: string, onEnd?: () => void) => void;
  /**
   * Say her "let me check your calendar, hmm…" while a reply is being
   * written. Plays at once if this device already has her voice for the line;
   * otherwise it is fetched quietly for next time and this turn stays silent.
   * A reply that is ready first waits for the line to finish.
   */
  sayFiller: (text: string) => void;
  cancel: () => void;
  /** What she is saying right now (for conversation mode); null when she is quiet. */
  now: () => VoiceNow | null;
  /**
   * Stop her at once: the person talked over her. Returns how much of the
   * reply they actually heard, or null when no reply was playing (a filler,
   * or nothing at all).
   */
  interrupt: () => CutOff | null;
}

export interface VoiceNow {
  /** The whole reply (and song) she is voicing — what an echo would sound like. */
  text: string;
  singing: boolean;
  /**
   * The loudest her voice was (dBFS, as played) over the last `windowMs`;
   * very low between clips. What an echo of her would be following.
   */
  loudness: (windowMs: number) => number;
}

export interface CutOff {
  /** Her words up to where she was stopped, estimated from playback time. */
  heard: string;
  /** Stopped during the warm-up or the song itself. */
  singing: boolean;
}

/** The clip she is on, so an interruption knows what was heard. */
interface Voicing {
  owner: string;
  text: string;
  parts: string[];
  part: number;
  startedAt: number;
  partMs: number;
  singing: boolean;
  filler: boolean;
  /** Her loudness through the clip (voiceLevel.ts). */
  levels: Float32Array;
}

// Clips are reused (fillers, warm-ups), so their levels are worked out once.
const levelCache = new WeakMap<SpeechResponse, Float32Array>();
function levelsOf(payload: SpeechResponse): Float32Array {
  let levels = levelCache.get(payload);
  if (!levels) {
    levels = voiceLevels(payload.audioBase64, payload.sampleRate, payload.channels);
    levelCache.set(payload, levels);
  }
  return levels;
}

// Filler clips, kept across app restarts: the lines are a small fixed set, and
// fetching one when it is needed would arrive after the reply it covers for.
const FILLER_CACHE = 'athena-filler-voice-v1';
const fillerMemory = new Map<string, SpeechResponse>();
const fillerKey = (text: string) => `https://athena.local/filler/${encodeURIComponent(text)}`;

async function cachedFiller(text: string): Promise<SpeechResponse | null> {
  const hit = fillerMemory.get(text);
  if (hit) return hit;
  try {
    const res = await (await caches.open(FILLER_CACHE)).match(fillerKey(text));
    if (!res) return null;
    const payload = (await res.json()) as SpeechResponse;
    if (!payload?.audioBase64) return null;
    fillerMemory.set(text, payload);
    return payload;
  } catch {
    return null; // Cache Storage unavailable: memory only.
  }
}

async function storeFiller(text: string, payload: SpeechResponse): Promise<void> {
  fillerMemory.set(text, payload);
  try {
    await (await caches.open(FILLER_CACHE)).put(
      fillerKey(text),
      new Response(JSON.stringify(payload), { headers: { 'Content-Type': 'application/json' } })
    );
  } catch {
    // Memory only this session.
  }
}

function pcmDurationMs(audioBase64: string, sampleRate: number, channels: number): number {
  const padding = audioBase64.endsWith('==') ? 2 : audioBase64.endsWith('=') ? 1 : 0;
  const byteLength = Math.max(0, Math.floor((audioBase64.length * 3) / 4) - padding);
  const samplesPerChannel = byteLength / 2 / Math.max(1, channels);
  return Math.ceil((samplesPerChannel / Math.max(1, sampleRate)) * 1000);
}

export function useSpeech(): Speech {
  const [isSupported, setIsSupported] = useState(false);
  const [enabled, setEnabled] = useState<boolean>(() => {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored === null ? true : stored === 'true';
  });
  const enabledRef = useRef(enabled);
  enabledRef.current = enabled;

  const bridgeRef = useRef<AthenaBridge | null>(null);
  const pendingRef = useRef<PendingSpeech | null>(null);
  // The prepared speech that last took the voice; a song waiting behind its
  // intro only plays if it still holds it.
  const ownerRef = useRef<string | null>(null);
  // While a filler plays, a reply that is ready waits on this instead of
  // cutting the line off mid-word.
  const fillerDoneRef = useRef<Promise<void> | null>(null);
  const fillerFetchesRef = useRef(new Set<string>());
  const voicingRef = useRef<Voicing | null>(null);

  const finish = useCallback((requestId?: string) => {
    const pending = pendingRef.current;
    if (!pending || (requestId && pending.id !== requestId)) return;
    pendingRef.current = null;
    pending.abort.abort();
    window.clearTimeout(pending.timer);
    try {
      pending.onEnd?.();
    } catch (error) {
      console.warn('useSpeech: onEnd failed', error);
    }
  }, []);

  /** Stop the clip that is playing, without giving up the voice. */
  const stopCurrent = useCallback(() => {
    bridgeRef.current?.sendToGameObject('AthenaBridge', 'StopSpeech');
    finish();
  }, [finish]);

  const cancel = useCallback(() => {
    ownerRef.current = null;
    voicingRef.current = null;
    stopCurrent();
  }, [stopCurrent]);

  const now = useCallback((): VoiceNow | null => {
    const voicing = voicingRef.current;
    if (!voicing || (!pendingRef.current && ownerRef.current === null)) return null;
    // Between parts (a part still generating) the last clip has run out, so
    // its levels end and she reads as silent, which is what she is.
    const loudness = (windowMs: number) => loudestOver(voicing.levels, Date.now() - voicing.startedAt, windowMs);
    return { text: voicing.text, singing: voicing.singing, loudness };
  }, []);

  const interrupt = useCallback((): CutOff | null => {
    const voicing = voicingRef.current;
    if (!pendingRef.current && ownerRef.current === null) return null;
    let cut: CutOff | null = null;
    if (voicing && !voicing.filler) {
      const heard = voicing.parts.slice(0, voicing.part);
      const current = voicing.parts[voicing.part];
      if (!voicing.singing && current) {
        // Speech is close enough to even-paced that elapsed time says roughly
        // how many of the sentence's words were out.
        const words = current.split(/\s+/);
        const elapsed = voicing.partMs > 0 ? (Date.now() - voicing.startedAt) / voicing.partMs : 0;
        const out = Math.floor(words.length * Math.min(1, Math.max(0, elapsed)));
        if (out >= words.length) heard.push(current);
        else if (out > 0) heard.push(`${words.slice(0, out).join(' ')}…`);
      }
      cut = { heard: heard.join(' '), singing: voicing.singing };
    }
    cancel();
    return cut;
  }, [cancel]);

  const attachUnity = useCallback((bridge: AthenaBridge) => {
    bridgeRef.current = bridge;
    setIsSupported(true);
  }, []);

  useEffect(() => {
    const onEnded = (event: Event) => {
      const requestId = (event as CustomEvent<{ requestId?: string }>).detail?.requestId;
      finish(requestId);
    };
    const onError = (event: Event) => {
      const requestId = (event as CustomEvent<{ requestId?: string }>).detail?.requestId;
      console.warn('Unity could not play Athena speech');
      finish(requestId);
    };

    window.addEventListener('athena-unity-speech-ended', onEnded);
    window.addEventListener('athena-unity-speech-error', onError);
    return () => {
      window.removeEventListener('athena-unity-speech-ended', onEnded);
      window.removeEventListener('athena-unity-speech-error', onError);
      bridgeRef.current?.sendToGameObject('AthenaBridge', 'StopSpeech');
      const pending = pendingRef.current;
      if (pending) {
        pending.abort.abort();
        window.clearTimeout(pending.timer);
        pendingRef.current = null;
      }
    };
  }, [finish]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, String(enabled));
    if (!enabled) cancel();
  }, [cancel, enabled]);

  /**
   * Fetch one generated clip. Resolves null on failure, timeout, or when
   * `signal` aborts. Each clip has its own controller so a spoken intro timing
   * out never takes the song down with it.
   */
  const fetchAudio = useCallback(
    (text: string, sing: boolean, signal: AbortSignal): Promise<SpeechResponse | null> =>
      new Promise((resolve) => {
        const own = new AbortController();
        if (signal.aborted) own.abort();
        else signal.addEventListener('abort', () => own.abort(), { once: true });
        const timer = window.setTimeout(() => {
          console.warn('useSpeech: voice generation timed out');
          own.abort();
          resolve(null);
        }, sing ? SING_GENERATION_TIMEOUT_MS : GENERATION_TIMEOUT_MS);

        void fetch(proxyUrl('/api/v1/speech'), {
          method: 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/json', ...CLIENT_HEADERS },
          body: JSON.stringify(sing ? { text, style: 'sing' } : { text }),
          signal: own.signal,
        })
          .then(async (response) => {
            if (!response.ok) throw new Error(`Speech request failed (${response.status})`);
            return (await response.json()) as SpeechResponse;
          })
          .then((payload) => {
            if (!payload.audioBase64 || !payload.sampleRate || !payload.channels) {
              throw new Error('Speech response did not contain playable PCM audio');
            }
            resolve(payload);
          })
          .catch((error: unknown) => {
            if ((error as { name?: string }).name !== 'AbortError') {
              console.warn('useSpeech: speech failed', error);
            }
            resolve(null);
          })
          .finally(() => window.clearTimeout(timer));
      }),
    []
  );

  const prepare = useCallback(
    (text: string, options?: { lyrics?: string }): PreparedSpeech => {
      const trimmed = text?.trim();
      const lyrics = options?.lyrics?.trim() || '';
      const id = crypto.randomUUID();
      const abort = new AbortController();
      let cancelled = false;
      let song: SpeechResponse | null = null;
      let songFailed = false;

      const active = enabledRef.current && !!trimmed;
      const chunks = active ? speechChunks(trimmed) : [];
      const partsP = chunks.map((part) => fetchAudio(part, false, abort.signal));
      const said = lyrics ? `${trimmed} ${lyrics}` : trimmed;
      // A song generates (~15 s) while she says her lead-in and hums a
      // warm-up; the hum is what keeps the switch to singing from being abrupt.
      const songP = active && lyrics ? fetchAudio(lyrics, true, abort.signal) : Promise.resolve(null);
      const warmupsP = active && lyrics ? loadWarmups() : Promise.resolve([] as SpeechResponse[]);
      const warmupStart = Math.floor(Math.random() * WARMUP_URLS.length);
      // The first part that voiced (normally the first): where she starts.
      // Null until known, -1 when every part failed.
      let first: number | null = null;
      const firstP = (async () => {
        for (let i = 0; i < partsP.length; i++) if (await partsP[i]) return i;
        return -1;
      })();
      void firstP.then((index) => {
        first = index;
      });
      void songP.then((payload) => {
        song = payload;
        songFailed = !!lyrics && !payload;
      });

      // Ready as soon as something can start: her first sentence, or the
      // song if the spoken line failed. False only when there is nothing to play.
      const ready = new Promise<boolean>((resolve) => {
        void firstP.then((index) => index >= 0 && resolve(!cancelled));
        void songP.then((payload) => payload && resolve(!cancelled));
        void Promise.all([firstP, songP]).then(([a, b]) => a < 0 && !b && resolve(false));
      });

      // Something else may take the voice while a song is still coming (a
      // newer reply, a cancel, Voice switched off); then the rest is dropped.
      const stillOwner = () =>
        !cancelled && ownerRef.current === id && enabledRef.current && !!bridgeRef.current;

      const playClip = (clipId: string, payload: SpeechResponse, onEnd?: () => void, part = chunks.length) => {
        stopCurrent();
        voicingRef.current = {
          owner: id,
          text: said,
          parts: chunks,
          part,
          startedAt: Date.now(),
          partMs: pcmDurationMs(payload.audioBase64, payload.sampleRate, payload.channels),
          // Every clip that isn't one of her spoken parts is a warm-up or the song.
          singing: part >= chunks.length,
          filler: false,
          levels: levelsOf(payload),
        };
        const timer = window.setTimeout(
          () => finish(clipId),
          pcmDurationMs(payload.audioBase64, payload.sampleRate, payload.channels) + 2000
        );
        // Only the final clip owns `abort`: finishing the lead-in or a hum
        // must not abort the song that is still being fetched.
        pendingRef.current = { id: clipId, abort: clipId === id ? abort : new AbortController(), timer, onEnd };
        const unityPayload: UnitySpeechPayload = { requestId: clipId, ...payload };
        bridgeRef.current?.sendToGameObject('AthenaBridge', 'PlaySpeech', JSON.stringify(unityPayload));
      };

      // Her spoken parts in order, each played when the one before it ends. A
      // part that is still generating is waited for; one that failed is
      // skipped. Something else taking the voice ends the run.
      const speakFrom = (index: number, done: () => void) => {
        if (index >= partsP.length) {
          done();
          return;
        }
        void partsP[index].then((clip) => {
          if (!stillOwner()) done();
          else if (!clip) speakFrom(index + 1, done);
          else {
            // Without a song the last part owns `abort`; with one, the song does.
            const clipId = index === partsP.length - 1 && !lyrics ? id : `${id}:part${index}`;
            playClip(clipId, clip, () => speakFrom(index + 1, done), index);
          }
        });
      };

      // After the lead-in: always one warm-up (the bridge from talking to
      // singing), more only while the song is still generating, then the song.
      const towardSong = (warmups: number, onEnd?: () => void) => {
        if (!stillOwner() || songFailed) {
          onEnd?.();
          return;
        }
        if (song && warmups > 0) {
          playClip(id, song, onEnd);
          return;
        }
        void warmupsP.then((clips) => {
          if (!stillOwner() || songFailed) {
            onEnd?.();
            return;
          }
          if (song && warmups > 0) {
            playClip(id, song, onEnd);
          } else if (warmups < MAX_WARMUPS && clips.length) {
            const clip = clips[(warmupStart + warmups) % clips.length];
            playClip(`${id}:warmup${warmups}`, clip, () => towardSong(warmups + 1, onEnd));
          } else {
            void songP.then((payload) => {
              if (!payload || !stillOwner()) onEnd?.();
              else playClip(id, payload, onEnd);
            });
          }
        });
      };

      const play = (onEnd?: () => void) => {
        const filler = fillerDoneRef.current;
        if (filler) {
          void filler.then(() => play(onEnd));
          return;
        }
        // Nothing voiced in time (the reveal stopped waiting): stay quiet
        // rather than start talking after the text has already landed.
        const start = first !== null && first >= 0 ? first : -1;
        if (cancelled || !enabledRef.current || !bridgeRef.current || (start < 0 && !song)) {
          onEnd?.();
          return;
        }
        ownerRef.current = id;
        // Finished (or dropped): she is quiet again unless something newer took over.
        const ended = () => {
          if (ownerRef.current === id) {
            ownerRef.current = null;
            voicingRef.current = null;
          }
          onEnd?.();
        };
        const afterSpeech = lyrics ? () => towardSong(0, ended) : ended;
        if (start >= 0) speakFrom(start, afterSpeech);
        else afterSpeech();
      };

      const cancelPrepared = () => {
        cancelled = true;
        abort.abort();
        if (ownerRef.current === id) cancel();
      };

      return { ready, play, cancel: cancelPrepared };
    },
    [cancel, fetchAudio, finish, stopCurrent]
  );

  const speak = useCallback(
    (text: string, onEnd?: () => void) => {
      const prepared = prepare(text);
      void prepared.ready.then((ok) => {
        if (ok) prepared.play(onEnd);
        else onEnd?.();
      });
    },
    [prepare]
  );

  const sayFiller = useCallback(
    (text: string) => {
      const line = text?.trim();
      if (!line || !enabledRef.current || !bridgeRef.current) return;
      void cachedFiller(line).then((clip) => {
        if (!clip) {
          // Not on this device yet: fetch it once, quietly, for next time.
          if (fillerFetchesRef.current.has(line)) return;
          fillerFetchesRef.current.add(line);
          void fetchAudio(line, false, new AbortController().signal)
            .then((payload) => (payload ? storeFiller(line, payload) : undefined))
            .finally(() => fillerFetchesRef.current.delete(line));
          return;
        }
        // Something is already speaking (a late reply, a greeting): skip.
        const bridge = bridgeRef.current;
        if (!enabledRef.current || !bridge || pendingRef.current) return;
        const clipId = `filler:${crypto.randomUUID()}`;
        let release: () => void = () => undefined;
        const done = new Promise<void>((resolve) => {
          release = resolve;
        });
        fillerDoneRef.current = done;
        voicingRef.current = {
          owner: clipId, text: line, parts: [], part: 0, startedAt: Date.now(), partMs: 0, singing: false, filler: true,
          levels: levelsOf(clip),
        };
        const end = () => {
          if (fillerDoneRef.current === done) fillerDoneRef.current = null;
          if (voicingRef.current?.owner === clipId) voicingRef.current = null;
          release();
        };
        const timer = window.setTimeout(
          () => finish(clipId),
          pcmDurationMs(clip.audioBase64, clip.sampleRate, clip.channels) + 2000
        );
        pendingRef.current = { id: clipId, abort: new AbortController(), timer, onEnd: end };
        const unityPayload: UnitySpeechPayload = { requestId: clipId, ...clip };
        bridge.sendToGameObject('AthenaBridge', 'PlaySpeech', JSON.stringify(unityPayload));
      });
    },
    [fetchAudio, finish]
  );

  const toggle = useCallback(() => setEnabled((value) => !value), []);

  return useMemo(
    () => ({ isSupported, enabled, attachUnity, toggle, prepare, speak, sayFiller, cancel, now, interrupt }),
    [attachUnity, cancel, enabled, interrupt, isSupported, now, prepare, sayFiller, speak, toggle]
  );
}
